import os,json,subprocess,pathlib,shutil,re
P=pathlib.Path
root=P("/srv/projects")
out={"roots":{},"pm2":{},"units":{},"references":{},"services":{}}
for n in ("telegram-robot-leads","iptvpn-bot"):
 p=root/n
 out["roots"][n]={"exists":p.is_dir() and not p.is_symlink(),"pm2_home_present":(p/".pm2").exists() or (p/".pm2").is_symlink(),"has_venv":(p/".venv").is_dir(),"has_ecosystem":(p/"ecosystem.config.js").is_file(),"has_start":(p/"start.sh").is_file(),"private":(p/"private").is_dir(),"data":(p/"data").is_dir()}
 for x in (p/"ecosystem.config.js",p/"start.sh"):
  if x.is_file():
   b=x.read_text(errors="replace")
   out["roots"][n][x.name+"_contains_legacy_root"]=any(s in b for s in ("/root/iptvpn_bot","/opt/telegram-robot-leads"))
cmd=["pm2","jlist"]
try:
 r=subprocess.run(cmd,env=dict(os.environ,PM2_HOME="/root/.pm2"),capture_output=True,text=True,timeout=15)
 out["pm2"]["query_exit"]=r.returncode
 if r.returncode==0:
  data=json.loads(r.stdout)
  out["pm2"]["apps"]=[{"name":a.get("name"),"pid":a.get("pid"),"pm_id":a.get("pm_id"),"status":(a.get("pm2_env")or{}).get("status"),"pm_cwd":(a.get("pm2_env")or{}).get("pm_cwd"),"exec_path":(a.get("pm2_env")or{}).get("pm_exec_path"),"interpreter":(a.get("pm2_env")or{}).get("exec_interpreter"),"args":(a.get("pm2_env")or{}).get("args"),"restart_time":(a.get("pm2_env")or{}).get("restart_time")} for a in data]
except Exception as e:out["pm2"]["error"]=type(e).__name__
for n in ("pm2-root","telegram-robot-leads","iptvpn-bot"):
 f=P("/etc/systemd/system")/(n+".service")
 v={"file":f.is_file(),"symlink":f.is_symlink()}
 try:
  r=subprocess.run(["systemctl","show",n,"--property=ActiveState,SubState,UnitFileState,MainPID"],capture_output=True,text=True,timeout=8)
  for line in r.stdout.splitlines():
   k,_,val=line.partition("=")
   if k in ("ActiveState","SubState","UnitFileState","MainPID"):v[k]=val
 except Exception:pass
 if f.is_file():
  t=f.read_text(errors="replace")
  v["mentions_global_pm2_home"]="/root/.pm2" in t
  v["mentions_project_pm2_home"]="/srv/projects/" in t
 out["units"][n]=v
for path in ("/root/iptvpn_bot","/opt/telegram-robot-leads","/root/.pm2","/etc/iptvpn-bot","/root/project-secrets/iptvpn_bot"):
 p=P(path);out["references"][path]={"exists":p.exists() or p.is_symlink(),"symlink":p.is_symlink(),"target":os.readlink(path) if p.is_symlink() else None}
dump=P("/root/.pm2/dump.pm2")
if dump.is_file():
 try:
  obj=json.loads(dump.read_text())
  out["pm2"]["dump_names"]=[{"name":a.get("name"),"cwd":(a.get("pm2_env")or{}).get("pm_cwd") or a.get("pm_cwd")} for a in obj if isinstance(a,dict)]
 except Exception:out["pm2"]["dump_read_failed"]=True
for n in ("ssh","nginx","pm2-root","lowcost-europa","fadego-staging","pink-iptv-backend"):
 out["services"][n]=subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip()
print(json.dumps(out,separators=(",",":"),ensure_ascii=True))
